1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	
11	const BASE_PREMIUMS = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	  rune: 25,
17	  moonstone: 25,
18	} as const;
19	
20	// The six priced types are the domain, so they are derived from the premium
21	// table rather than restated: a type nobody prices cannot be insured. The
22	// unknown-type case (broomstick) is still a runtime error the tests will drive.
23	type ItemType = keyof typeof BASE_PREMIUMS;
24	
25	// Components (as opposed to main items) are the only things the block rule
26	// applies to, so the distinction has to be data, not a price coincidence.
27	// Typed as a set of ItemType so a component can never name an unpriced type.
28	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
29	
30	const PERCENT_WHOLE = 100;
31	
32	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
33	// floating-point error that shifts the spec's round-up in MHPCO's favour.
34	const percentOf = (percent: number, amount: number): number =>
35	  (amount * percent) / PERCENT_WHOLE;
36	
37	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
38	// round up, payouts (MHPCO pays) round down.
39	const roundPremiumInMHPCOsFavour = Math.ceil;
40	
41	export type ScenarioResult = { premium: number };
42	
43	// Items carry attributes no rule reads yet (material/enchantment/cursed drive
44	// the surcharge and claim tests still to come). They are typed as optional so
45	// the scenarios the tests actually send typecheck, without pricing them.
46	type Item = {
47	  type: ItemType;
48	  material?: string;
49	  enchantment?: number;
50	  cursed?: boolean;
51	};
52	
53	type Step = { op: string; items: Item[] };
54	
55	type Customer = { yearsWithMHPCO: number };
56	
57	// `op` is still unread: the claim tests will reach for it.
58	type Scenario = {
59	  customer: Customer;
60	  steps: Step[];
61	};
62	
63	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
64	
65	const sumBasePremiums = (items: Item[]): number =>
66	  items.reduce((total, item) => total + basePremiumForItem(item), 0);
67	
68	// Groups of items that are "alike" — same type. The type is kept alongside the
69	// items because the block rule asks about it; recovering it from items[0] would
70	// make every reader re-derive that a group is non-empty and homogeneous.
71	type AlikeItems = { type: ItemType; items: Item[] };
72	
73	const groupByType = (items: Item[]): AlikeItems[] => {
74	  const groups = new Map<ItemType, Item[]>();
75	  for (const item of items) {
76	    const group = groups.get(item.type) ?? [];
77	    group.push(item);
78	    groups.set(item.type, group);
79	  }
80	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
81	};
82	
83	// A block is a discount on the components' combined base premium, not a flat
84	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
85	// 20 % stays visible as the rule it is.
86	const blockBasePremium = (items: Item[]): number => {
87	  const undiscounted = sumBasePremiums(items);
88	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
89	};
90	
91	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
92	// pile is never cheaper than the block it contains. Components only — three
93	// swords are three separate insurances, not a discounted building block.
94	const formsABlock = ({ type, items }: AlikeItems): boolean =>
95	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
96	
97	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
98	  formsABlock(alikeItems)
99	    ? blockBasePremium(alikeItems.items)
100	    : sumBasePremiums(alikeItems.items);
101	
102	// Priced per group of alike items rather than over the whole list, so 3 runes
103	// and 3 moonstones each form their own block.
104	const policyBasePremiumFor = (items: Item[]): number =>
105	  groupByType(items)
106	    .map(basePremiumForGroup)
107	    .reduce((total, groupPremium) => total + groupPremium, 0);
108	
109	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
110	  applies ? percentOf(percent, amount) : 0;
111	
112	// Each item-specific surcharge is a percentage of the affected item's OWN base
113	// premium, so every rule reads as "this much, when this holds". The terms are
114	// summed rather than chosen between: an item can trigger several at once.
115	//
116	// Deliberately two explicit terms rather than a table of rules. The shared
117	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
118	// a threshold over an optional number), and nothing in the remaining spec adds
119	// a third item-specific surcharge to generalise over.
120	const surchargeFor = (item: Item): number => {
121	  const base = basePremiumForItem(item);
122	  return (
123	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
124	    percentOfWhen(
125	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
126	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
127	      base,
128	    )
129	  );
130	};
131	
132	// Charged alongside the policy base premium — never folded into it, or the
133	// policy-wide modifiers would compound on top of them.
134	const itemSurchargesFor = (items: Item[]): number =>
135	  items.reduce((total, item) => total + surchargeFor(item), 0);
136	
137	const quoteFor = (items: Item[], customer: Customer): ScenarioResult => {
138	  const policyBasePremium = policyBasePremiumFor(items);
139	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
140	  const loyaltyDiscount = percentOfWhen(
141	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
142	    LOYALTY_DISCOUNT_PERCENT,
143	    policyBasePremium,
144	  );
145	  const premium = roundPremiumInMHPCOsFavour(
146	    policyBasePremium +
147	      itemSurchargesFor(items) +
148	      firstInsuranceSurcharge -
149	      loyaltyDiscount +
150	      PROCESSING_FEE,
151	  );
152	  return { premium };
153	};
154	
155	// Every scenario so far holds exactly one quote step, so only the first is
156	// priced. The follow-up-contract discount test will drive priced-per-step.
157	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
158	  const [firstStep] = scenario.steps;
159	  return { results: [quoteFor(firstStep.items, scenario.customer)] };
160	};
